<?php declare(strict_types=1); if(!defined('ABSPATH')){exit;} ?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OptiGrid Sandbox</title><style>body{margin:0;background:#f3f5f7;color:#1d2327;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.box{max-width:720px;margin:6vh auto;background:#fff;border-radius:14px;box-shadow:0 12px 35px #0002;padding:32px}.brand{font-size:.85rem;text-transform:uppercase;letter-spacing:.12em;color:#646970}.amount{font-size:2rem;font-weight:700}.meta{background:#f6f7f7;padding:16px;border-radius:8px}.scenarios{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:24px}.scenario{padding:16px;border:1px solid #c3c4c7;border-radius:8px;background:#fff;cursor:pointer;text-align:left}.scenario:hover{border-color:#2271b1}.delay{margin:22px 0}.notice{padding:14px;border-left:4px solid #2271b1;background:#f0f6fc}.approved{border-color:#00a32a}.rejected,.technical_error{border-color:#d63638}.pending{border-color:#dba617}.cancelled{border-color:#646970}</style></head><body><main class="box"><div class="brand">OptiGrid Sandbox Payment Gateway</div><h1>Simulación de pago</h1><div class="meta"><p><strong>Plan:</strong> <?php echo esc_html((string)($plan['name']??'Plan')); ?></p><p class="amount"><?php echo esc_html(number_format_i18n((float)$order['amount'],2).' '.strtoupper((string)$order['currency'])); ?></p><p><strong>Orden:</strong> <code><?php echo esc_html((string)$order['public_id']); ?></code></p></div>
<?php if($result!==''): ?><div class="notice <?php echo esc_attr($result); ?>"><strong>Resultado registrado:</strong> <?php echo esc_html($result); ?>. La pestaña original actualizará el estado automáticamente.</div><p><button onclick="window.close()">Cerrar ventana</button></p>
<?php elseif($order['status']!=='pending'): ?><div class="notice">Esta orden ya está en estado <strong><?php echo esc_html((string)$order['status']); ?></strong>.</div>
<?php else: ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" data-sandbox-form><input type="hidden" name="action" value="<?php echo esc_attr(OptiGrid_Subscriptions_Sandbox_Portal_Controller::process_action()); ?>"><input type="hidden" name="order" value="<?php echo esc_attr((string)$order['public_id']); ?>"><input type="hidden" name="scenario" value="pending" data-scenario><?php wp_nonce_field('sandbox_process_'.(string)$order['public_id']); ?><div class="delay"><label><strong>Retardo de respuesta:</strong> <select data-delay><option value="0">Instantánea</option><option value="5">5 segundos</option><option value="30">30 segundos</option><option value="120">2 minutos</option></select></label> <span data-countdown></span></div><div class="scenarios"><?php foreach(['approved'=>'Aprobar pago','rejected'=>'Rechazar pago','pending'=>'Dejar pendiente','cancelled'=>'Cancelar operación','technical_error'=>'Error técnico'] as $key=>$label): ?><button type="button" class="scenario <?php echo esc_attr($key); ?>" data-result="<?php echo esc_attr($key); ?>"><strong><?php echo esc_html($label); ?></strong><br><small>Simular resultado <?php echo esc_html($key); ?></small></button><?php endforeach; ?></div></form><script>(function(){const f=document.querySelector('[data-sandbox-form]');const s=f.querySelector('[data-scenario]');const d=f.querySelector('[data-delay]');const c=f.querySelector('[data-countdown]');f.querySelectorAll('[data-result]').forEach(b=>b.addEventListener('click',()=>{s.value=b.dataset.result;let n=parseInt(d.value,10)||0;if(!n){f.submit();return;}f.querySelectorAll('button').forEach(x=>x.disabled=true);c.textContent='Enviando en '+n+' s';const t=setInterval(()=>{n--;c.textContent='Enviando en '+n+' s';if(n<=0){clearInterval(t);f.submit();}},1000);}));})();</script><?php endif; ?></main></body></html>
